function [b_min, b_mean, bm] = survey_field(bm, n)
%SURVEY_FIELD  The field along one orbit: the least and the mean of the n samples of its strength bm [T] (the sum from -0, as the
%   code's sum).
%   length: 8
%   bm: inout real[1][*] (passed a plain number)
%   n: int (passed a whole number)
%   returns b_min: real[1] (passed a plain number)
%   returns b_mean: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    b_min = 0;
    b_mean = 0;
    b_min = 1.7976931348623157e+308;
    s = (-(0));
    for k = (0):((n) - 1)
        b_min = asils.pc.fmin(b_min, bm((k) + 1));
        s = (s + bm((k) + 1));
    end
    b_mean = (s / n);
end
